"""Read-only source-media checks and exact review copies; no provider actions."""
from pathlib import Path
import json,hashlib,subprocess,shutil,re
V=Path(__file__).resolve().parents[1];Q=V/'qa';ROOT=Path.cwd()/'runs/shizhen-macro-opening-20261027/MC01-02-1080p-v3';fetch=json.loads((V/'fetch-result.json').read_text());source=ROOT/fetch['artifact_path'];sha=hashlib.sha256(source.read_bytes()).hexdigest();assert sha==fetch['sha256'];destination=V.parent/'失帧-市政异常-1080p-2.0-认可方案03.mp4'
if destination.exists():assert hashlib.sha256(destination.read_bytes()).hexdigest()==sha
else:shutil.copyfile(source,destination)
probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration,size:stream=codec_type,codec_name,width,height,avg_frame_rate,r_frame_rate,nb_frames,duration,sample_rate,channels','-of','json',str(source)]));video=next(s for s in probe['streams'] if s['codec_type']=='video');assert (video['width'],video['height'])==(1920,1080);assert any(s['codec_type']=='audio' for s in probe['streams'])
subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(source),'-f','null','-'],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)
frames=Q/'frames';frames.mkdir(exist_ok=True);assert not list(frames.glob('frame-*.png'))
run=subprocess.run(['ffmpeg','-hide_banner','-loglevel','info','-i',str(source),'-vf',"select='isnan(prev_selected_t)+gte(t-prev_selected_t,0.5)',showinfo",'-vsync','0',str(frames/'frame-%02d.png')],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,text=True,check=True);timestamps=[float(t) for t in re.findall(r'pts_time:([0-9.]+)',run.stderr)]
(Q/'frame-index.json').write_text(json.dumps({'source_sha256':sha,'frames':[{'path':str(f),'source_pts_seconds':t} for f,t in zip(sorted(frames.glob('frame-*.png')),timestamps)]},ensure_ascii=False,indent=2)+'\n')
run=subprocess.run(['ffmpeg','-hide_banner','-loglevel','info','-i',str(source),'-vf',"select='gt(scene,0.10)',showinfo",'-an','-f','null','-'],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,text=True,check=True);cuts=[float(t) for t in re.findall(r'pts_time:([0-9.]+)',run.stderr)]
(Q/'technical-probe.json').write_text(json.dumps({'source_path':str(source),'source_sha256':sha,'size_bytes':source.stat().st_size,'review_copy':str(destination),'probe':probe,'full_decode':True,'original_rate_preserved':True,'detected_scene_change_pts':cuts,'fps_note':'r_frame_rate is not measured playback rate; source timestamps are retained','quality':'NOT_EVALUATED','human_acceptance':'NOT_EVALUATED'},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'source_path':str(source.resolve()),'sha256':sha,'size_bytes':source.stat().st_size,'resolution':[video['width'],video['height']],'duration':probe['format']['duration'],'frames_extracted':len(timestamps),'scene_change_pts':cuts}))
